from pathlib import Path
root=Path(__file__).resolve().parent
p=root/'site/referral-progress.js'
s=p.read_text()
pos=s.index('const date=')
s=s[:pos]+'''// The profile controls and dashboard filters share the same values and wording.
const options={assessment:[['pending','Not yet'],['accepted','Yes']],approval:[['waiting','Waiting for approval'],['missing','Approved — paperwork needed'],['received','Approved — paperwork received']],payment:[['waiting','Not confirmed'],['missing','Confirmed — paperwork needed'],['received','Confirmed — paperwork received']],moveStatus:[['none','Not scheduled'],['scheduled','Scheduled'],['moved','Moved in']]};
const filterOptions=[...options.assessment.map(([v,label])=>['assessment:'+v,'Assessment passed / building accepted? — '+label]),...options.approval.map(([v,label])=>['approval:'+v,label]),...options.payment.map(([v,label])=>['payment:'+v,'Payment arrangements — '+label]),...options.moveStatus.filter(([v])=>v!=='moved').map(([v,label])=>['moveStatus:'+v,'Move-in — '+label])];
function matchesProgress(p,filter){if(!filter||filter==='all')return true;const [field,value]=filter.split(':');if(field==='payment')return p.privatePay&&p.approval===value;if(field==='approval')return !p.privatePay&&p.approval===value;return ['assessment','moveStatus'].includes(field)&&p[field]===value;}
function ccaKey(value){return String(value||'').trim().toLowerCase().replace(/\\s+/g,' ')||'__not_recorded__';}
function matchesWaitingCCA(l,p,key){return p.waiting&&(!key||key==='all'||ccaKey(l.cca)===key);}
''' +s[pos:]
s=s.replace('summary,apply,statuses,date,waitingOptions','summary,apply,statuses,date,waitingOptions,options,filterOptions,matchesProgress,ccaKey,matchesWaitingCCA')
p.write_text(s)
p=root/'site/app.js';s=p.read_text()
a=s.index('function providerKey(');b=s.index('function progressDashboard',a)
s=s[:a]+'''function providerOptions(selected){const rows=new Map();for(const l of TL.visibleLeads().filter(TL.isOpen)){const p=TL.referralSummary(l);if(p.waiting){const key=window.TLReferral.ccaKey(l.cca),old=rows.get(key)||{label:String(l.cca||'').trim()||'CCA not recorded',count:0};old.count++;rows.set(key,old);}}return '<option value="all">All CCAs</option>'+[...rows].sort((a,b)=>a[1].label.localeCompare(b[1].label)).map(([key,v])=>`<option value="${esc(key)}" ${selected===key?'selected':''}>${esc(v.label)} · ${v.count}</option>`).join('');}
''' +s[b:]
s=s.replace("...window.TLReferral.statuses.filter(x=>!['moved','county'].includes(x[0]))","...window.TLReferral.filterOptions")
s=s.replace('All open stages','All profile stages')
s=s.replace('<label>Waiting on provider<select','<label>Waiting on<select')
s=s.replace("if(UI.progressStage&&UI.progressStage!=='all')ls=ls.filter(l=>(UI.progressStage==='approval'?['approval','county'].includes(TL.referralSummary(l).stage):TL.referralSummary(l).stage===UI.progressStage));","if(UI.progressStage&&UI.progressStage!=='all')ls=ls.filter(l=>window.TLReferral.matchesProgress(TL.referralSummary(l),UI.progressStage));")
s=s.replace("return p.waiting&&providerKey(p.provider)===UI.waitProvider;","return window.TLReferral.matchesWaitingCCA(l,p,UI.waitProvider);")
s=s.replace('Open a referral to see when waiting was recorded, the latest dated update, and the next follow-up.','Stages match the Progress options on each lead profile. Choose a CCA under Waiting on to see its referrals waiting for approval.')
s=s.replace("[['pending','Not yet'],['accepted','Yes']],p.assessment","window.TLReferral.options.assessment,p.assessment")
s=s.replace("priv?[['waiting','Not confirmed'],['missing','Confirmed — paperwork needed'],['received','Confirmed — paperwork received']]:[['waiting','Waiting for approval'],['missing','Approved — paperwork needed'],['received','Approved — paperwork received']]","priv?window.TLReferral.options.payment:window.TLReferral.options.approval")
s=s.replace("[['none','Not scheduled'],['scheduled','Scheduled'],['moved','Moved in']],p.moveStatus","window.TLReferral.options.moveStatus,p.moveStatus")
s=s.replace("UI.progressStage=$('#homeStage').value;UI.waitProvider=$('#homeProvider').value;","UI.progressStage=$('#homeStage').value;UI.waitProvider=$('#homeProvider').value;UI.issue='all';")
s=s.replace("if(a==='oldWaiting'){UI.waitingAge=true;","if(a==='oldWaiting'){UI.issue='all';UI.waitingAge=true;")
p.write_text(s)
for f in ['app.js','referral-progress.js']:(root/'dist'/f).write_text((root/'site'/f).read_text())

(root/'test/profile-filters.test.mjs').write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport vm from 'node:vm';\nimport {readFileSync} from 'node:fs';\nimport {initialState,engine} from '../server/engine.mjs';\nconst ctx={window:{},Date};vm.createContext(ctx);vm.runInContext(readFileSync(new URL('../site/referral-progress.js',import.meta.url),'utf8'),ctx);\nconst R=ctx.window.TLReferral;\nfunction fixture(assessment='pending',approval='waiting',cca='Example CCA',payer='ALW waiver'){\n const tl=engine(initialState(false),'u0'),l=tl.createLead({first:'Filter',last:'Example',building:'hallmark',payer,cca,rep:'u3'},'',{assessment,approval,reason:'',moveStatus:'none',moveDate:'',due:'2026-12-01',note:''});\n return {l,p:tl.referralSummary(l)};\n}\ntest('approval filters reflect the saved profile even before assessment is accepted',()=>{\n const {p}=fixture();assert.equal(p.stage,'assessment');\n assert.ok(R.matchesProgress(p,'approval:waiting'));assert.ok(R.matchesProgress(p,'assessment:pending'));\n assert.equal(R.matchesProgress(p,'approval:missing'),false);\n const approved=fixture('pending','missing').p;\n assert.ok(R.matchesProgress(approved,'approval:missing'));assert.equal(R.matchesProgress(approved,'approval:waiting'),false);\n});\ntest('verified paperwork remains findable when county requirements determine the next step',()=>{\n const {p}=fixture('accepted','received');assert.equal(p.stage,'county');\n assert.ok(R.matchesProgress(p,'approval:received'));assert.equal(R.matchesProgress(p,'approval:waiting'),false);\n assert.ok(R.matchesProgress(p,'assessment:accepted'));assert.ok(R.matchesProgress(p,'moveStatus:none'));\n});\ntest('waiting on CCA excludes approved referrals and uses assigned CCA instead of roadmap fallback',()=>{\n const {l,p}=fixture('pending','waiting',' Example   CCA ');\n assert.ok(R.matchesWaitingCCA(l,p,R.ccaKey('example cca')));\n assert.equal(R.matchesWaitingCCA(l,p,R.ccaKey('Other CCA')),false);\n assert.equal(R.matchesWaitingCCA(l,fixture('accepted','missing').p,R.ccaKey(l.cca)),false);\n const missing=fixture('pending','waiting','');assert.ok(R.matchesWaitingCCA(missing.l,missing.p,R.ccaKey('')));\n assert.equal(R.matchesWaitingCCA(missing.l,missing.p,R.ccaKey(missing.p.provider||'Roadmap CCA')),false);\n assert.notEqual(R.ccaKey('A&B'),R.ccaKey('AB'));\n});\ntest('private payment confirmation is separate from program approval and waiting CCA',()=>{\n const {l,p}=fixture('pending','waiting','Example CCA','Private pay');\n assert.ok(R.matchesProgress(p,'payment:waiting'));assert.equal(R.matchesProgress(p,'approval:waiting'),false);\n assert.equal(R.matchesWaitingCCA(l,p,'all'),false);\n});\n")
